static inline int16_t cnn_relu_shift(cnn_acc_t v, int shift)
{
    if (shift >= 0) v >>= shift;
    else            v <<= -shift;
    if (v <= 0) return 0;
    if (v > 32767) return 32767;
    return (int16_t)v;
}

/* x is slot-major: x[t*CNN_C + c]. logits are integer FC accumulators. */
static void cnn_run_q15(const int16_t *x, cnn_acc_t *logits)
{
    int16_t a1[CNN_C1][CNN_SLOTS];
    int16_t a2[CNN_C2][CNN_SLOTS];
    int o, c, t, k;

    for (o = 0; o < CNN_C1; o++) {
        for (t = 0; t < CNN_SLOTS; t++) {
            cnn_acc_t acc = (cnn_acc_t)cnn_b1[o];
            for (c = 0; c < CNN_C; c++) {
                for (k = 0; k < CNN_K; k++) {
                    int ti = t + k - CNN_K/2;
                    if (ti >= 0 && ti < CNN_SLOTS) {
                        size_t wi = ((size_t)o * CNN_C + c) * CNN_K + k;
                        acc += (cnn_acc_t)x[ti * CNN_C + c] * (cnn_acc_t)cnn_w1[wi];
                    }
                }
            }
            a1[o][t] = cnn_relu_shift(acc, CNN_SHIFT1);
        }
    }

    for (o = 0; o < CNN_C2; o++) {
        for (t = 0; t < CNN_SLOTS; t++) {
            cnn_acc_t acc = (cnn_acc_t)cnn_b2[o];
            for (c = 0; c < CNN_C1; c++) {
                for (k = 0; k < CNN_K; k++) {
                    int ti = t + k - CNN_K/2;
                    if (ti >= 0 && ti < CNN_SLOTS) {
                        size_t wi = ((size_t)o * CNN_C1 + c) * CNN_K + k;
                        acc += (cnn_acc_t)a1[c][ti] * (cnn_acc_t)cnn_w2[wi];
                    }
                }
            }
            a2[o][t] = cnn_relu_shift(acc, CNN_SHIFT2);
        }
    }

    for (o = 0; o < CNN_NCLASS; o++) {
        cnn_acc_t acc = (cnn_acc_t)cnn_bf[o];
        for (c = 0; c < CNN_C2; c++) {
            for (t = 0; t < CNN_SLOTS; t++) {
                size_t fi = (size_t)c * CNN_SLOTS + t;
                size_t wi = (size_t)o * (CNN_C2 * CNN_SLOTS) + fi;
                acc += (cnn_acc_t)a2[c][t] * (cnn_acc_t)cnn_wf[wi];
            }
        }
        logits[o] = acc;
    }
}

static int cnn_decide(const cnn_acc_t *logits)
{
    int i, best = 0;
    for (i = 1; i < CNN_NCLASS; i++)
        if (logits[i] > logits[best]) best = i;
    return best;
}

